//! The iterative inverse of PolyMaps with no inverse coefficients, against
//! C's bit for bit (polymap.c Transform with IterInverse set): an initial
//! guess from the linear truncation of the forward transformation
//! (LinearGuess), Newton-Raphson steps solved by palDmat, and convergence
//! when |dx|^2 <= tol^2 |x|^2.
//!
//! `poly_iter_inverse_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/poly_iter_inverse_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "poly_iter_inverse_oracle/cases.rs"]
mod cases;

use starlink_ast::coords::PointSet;
use starlink_ast::mappings::{Mapping, PolyMap, PolyTerm};

/// The PolyMap a case builds: coefficients as `astPolyMap` takes them, each
/// a coefficient, a 1-based output and one power per input, and options
/// `NiterInverse` and `TolInverse` given as `name=value` pairs.
fn polymap(n: usize, coeffs: &[f64], opts: &str) -> PolyMap {
    let terms: Vec<PolyTerm> = coeffs
        .chunks(2 + n)
        .map(|c| PolyTerm {
            coeff: c[0],
            out_axis: c[1] as usize,
            powers: c[2..].iter().map(|&p| p as usize).collect(),
        })
        .collect();
    let mut pm = PolyMap::new(n, n, &terms, None).unwrap();
    pm.set_iter_inverse(true).unwrap();
    for opt in opts.split(',').filter(|o| !o.is_empty()) {
        let (name, value) = opt.split_once('=').unwrap();
        match name {
            "TolInverse" => pm.set_tol_inverse(value.parse().unwrap()),
            "NiterInverse" => pm.set_niter_inverse(value.parse().unwrap()),
            other => panic!("unknown option {other}"),
        }
    }
    pm
}

#[test]
fn iterative_inverse_matches_the_c_library_bit_for_bit() {
    let mut failures = Vec::new();
    for &(name, n, coeffs, opts, npoint, out, want) in cases::CASES {
        let pm = polymap(n, coeffs, opts);
        let cols: Vec<&[f64]> = out.chunks(npoint).collect();
        let got = pm
            .transform(&PointSet::from_columns(&cols).unwrap(), false)
            .unwrap();
        for ip in 0..npoint {
            for axis in 0..n {
                let (g, w) = (got.point(ip)[axis], want[axis * npoint + ip]);
                if g.to_bits() != w.to_bits() {
                    failures.push(format!("{name} point {ip} axis {axis}: {g:e}, C {w:e}"));
                }
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
